import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Share of the remaining items' total value that would no longer fit if this candidate were taken next (opportunity cost of blocking)."""
    v = np.asarray(values, dtype=float)
    w = np.asarray(weights, dtype=float)
    k = v.size
    if k == 0:
        return np.zeros(0)
    total_v = float(v.sum())
    if total_v <= 0.0:
        return np.zeros(k)
    # blocked[i, j] = taking i makes j infeasible (j != i)
    blocked = (w[:, None] + w[None, :]) > float(remaining)
    np.fill_diagonal(blocked, False)
    lost = blocked.astype(float) @ v          # value destroyed by choosing i
    return lost / total_v
